#include <bits/stdc++.h>
using namespace std;

typedef long long ll;
const int MAXN=5007;
const ll INF=1e9;

struct Edge {
    int from, to;
    ll cap, cost, flow;
    Edge(int u, int v, ll c, ll co): from(u), to(v), cap(c), cost(co), flow(0) {}
};

vector<Edge> edges;
vector<int> g[MAXN];
ll dist[MAXN], phi[MAXN];
int parent[MAXN];

void add_edge(int u, int v, ll cap, ll cost) {
    g[u].push_back((int)edges.size());
    edges.emplace_back(u, v, cap, cost);
    g[v].push_back((int)edges.size());
    edges.emplace_back(v, u, 0, -cost);
}

void init_phi(int s, int n) {
    for (int i=0; i<MAXN; i++) phi[i]=INF;
    phi[s]=0;
    for (int i=0; i<n; i++) {
        for (auto &e: edges) {
            if (e.cap==e.flow) continue;
            int u=e.from, v=e.to;
            ll c=e.cost;
            if (phi[u]==INF) continue;
            phi[v]=min(phi[v], phi[u]+c);
        }
    }
}

void run_dijkstra(int s) {
    for (int i=0; i<MAXN; i++) dist[i]=INF;
    dist[s]=0;
    set<pair<ll,int>> pq;
    pq.insert({0,s});
    while (!pq.empty()) {
        int v=pq.begin()->second;
        pq.erase(pq.begin());
        for (int eid: g[v]) {
            auto &e=edges[eid];
            if (e.cap==e.flow) continue;
            int to=e.to;
            ll costVal=e.cost+phi[v]-phi[to];
            if (dist[v]+costVal<dist[to]) {
                pq.erase({dist[to], to});
                dist[to]=dist[v]+costVal;
                parent[to]=eid;
                pq.insert({dist[to], to});
            }
        }
    }
}

pair<ll,ll> min_cost_max_flow(int s, int t) {
    init_phi(s, 50);
    run_dijkstra(s);
    ll flow=0, cost=0;
    while (true) {
        if (dist[t]==INF) break;
        ll pushed=INF, sum=0;
        for (int tmp=t; tmp!=s; tmp=edges[parent[tmp]].from) {
            int eid=parent[tmp];
            pushed=min(pushed, edges[eid].cap - edges[eid].flow);
            sum+=edges[eid].cost;
        }
        flow+=pushed;
        cost+=pushed*sum;
        for (int tmp=t; tmp!=s; tmp=edges[parent[tmp]].from) {
            int eid=parent[tmp];
            edges[eid].flow+=pushed;
            edges[eid^1].flow-=pushed;
        }
        run_dijkstra(s);
        for (int i=0; i<MAXN; i++) phi[i]=dist[i];
    }
    return {cost, flow};
}

void solve() {
    int n,m,k,c,d;
    cin>>n>>m>>k>>c>>d;
    vector<int> cnts(n,0);
    for (int i=0; i<k; i++) {
        int ai;
        cin>>ai;
        ai--;
        cnts[ai]++;
    }
    for (int i=0; i<n; i++) {
        add_edge(5000, i, cnts[i], 0);
    }
    for (int it=0; it<m; it++) {
        int u,v;
        cin>>u>>v;
        u--; v--;
        for (int i=0; i<99; i++) {
            ll costVal=d+2*d*i;
            add_edge(u+i*50, v+(i+1)*50, 1, costVal);
            add_edge(v+i*50, u+(i+1)*50, 1, costVal);
        }
    }
    for (int i=0; i<=99; i++) {
        add_edge(0+i*50, 5001, INF, c*i);
    }
    for (int i=0; i<n; i++) {
        for (int j=0; j<99; j++) {
            add_edge(i+j*50, i+(j+1)*50, INF, 0);
        }
    }
    auto p=min_cost_max_flow(5000, 5001);
    assert(p.second==k);
    cout<<p.first;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    cout<<fixed<<setprecision(20);
    solve();
    return 0;
}
